mapper.select:
SELECT COUNT(1) AS unitCnt, 
       COUNT(DISTINCT t.clinic_label) AS labelCnt 
FROM clinic_for_regist t
WHERE RAWTOHEX(t.clinic_label) IN (
          SELECT RAWTOHEX(i.clinic_label)
          FROM clinic_index i
          WHERE i.clinic_class = 10
            AND RAWTOHEX(i.clinic_label) NOT LIKE #{olNurseHex}
            AND RAWTOHEX(i.clinic_label) NOT LIKE #{olPharmHex}
            AND RAWTOHEX(i.clinic_label) NOT LIKE #{olTeamHex}
            AND RAWTOHEX(i.clinic_label) NOT LIKE #{revisitHex}
            AND RAWTOHEX(i.clinic_label) != #{quankeHex}
      )
  AND t.clinic_date >= TO_DATE(#{startDate}, 'YYYY-MM-DD')
  AND t.clinic_date < TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1
  AND t.registration_limits > 1

SELECT TRUNC(t.clinic_date) AS itemDate, 
       COUNT(1) AS unitCnt, 
       COUNT(DISTINCT t.clinic_label) AS labelCnt 
FROM clinic_for_regist t
WHERE RAWTOHEX(t.clinic_label) IN (
          SELECT RAWTOHEX(i.clinic_label)
          FROM clinic_index i
          WHERE i.clinic_class = 10
            AND RAWTOHEX(i.clinic_label) NOT LIKE #{olNurseHex}
            AND RAWTOHEX(i.clinic_label) NOT LIKE #{olPharmHex}
            AND RAWTOHEX(i.clinic_label) NOT LIKE #{olTeamHex}
            AND RAWTOHEX(i.clinic_label) NOT LIKE #{revisitHex}
            AND RAWTOHEX(i.clinic_label) != #{quankeHex}
      )
  AND t.clinic_date >= TO_DATE(#{startDate}, 'YYYY-MM-DD')
  AND t.clinic_date < TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1
  AND t.registration_limits > 1
GROUP BY TRUNC(t.clinic_date)
ORDER BY itemDate DESC
